ValidationRule.errorConditionFormula:
AND(NOT (
(CONTAINS('System Admin', $User.FirstName) && CONTAINS('Updates', $User.LastName)) ||
(CONTAINS('Automated', $User.FirstName) && CONTAINS('Process', $User.LastName))
),
CONTAINS(RecordType.DeveloperName,'Qantas_Freight'),
NOT(ISPICKVAL( Type , 'Invalid Case') ) ,NOT( ISPICKVAL( Freight_Resolve_Reason__c , 'Duplicate Case')), NOT(ISCHANGED( OwnerId )),   NOT(ISPICKVAL( Status , 'Closed')),  
OR(AND(ISPICKVAL(Origin,'FRT Phone'), ISBLANK( Freight_AWB_Number__c ),OR( ISBLANK( Freight_Port__c ), ISBLANK(                       TEXT( Product__c ) ) )),
AND(NOT(ISNEW()),ISBLANK( Freight_AWB_Number__c ),OR( ISBLANK( Freight_Port__c ), ISBLANK( TEXT( Product__c ) )),OR( ISPICKVAL(Origin, 'FRT Bookings'), ISPICKVAL(Origin,'FRT Claims'), ISPICKVAL(Origin,'FRT Cust Service'),  ISPICKVAL(Origin,'FRT Sales Support'),ISPICKVAL(Origin,'FRT Export Spl Moves'),ISPICKVAL(Origin,'FRT Spl Moves'),ISPICKVAL(Origin,'FRT Chat'),ISPICKVAL(Origin,'Web'), ISPICKVAL(Origin,'FRT Portal'))
)
))
